arguments.command:
python3 - <<'PY'
from pathlib import Path
import shutil
root = Path('file-generation-test')
# Remove any mistakenly literal brace-expansion directories.
for p in sorted(root.rglob('*'), reverse=True):
    if '{' in p.name or '}' in p.name:
        shutil.rmtree(p)
# Create intended hierarchy.
for name in ['inputs', 'outputs', 'logs', 'manifests', 'scripts', 'tmp']:
    (root / name).mkdir(parents=True, exist_ok=True)
for shard in range(10):
    for batch in range(3):
        (root / 'shards' / f'shard-{shard:02d}' / f'batch-{batch:03d}').mkdir(parents=True, exist_ok=True)
# Placeholders.
for d in [root, *[p for p in root.rglob('*') if p.is_dir()]]:
    (d / '.gitkeep').touch()
PY
find file-generation-test -type d | sort
